async () => {
const g=document.querySelector('vaadin-grid');
const seen=new Map();
for(let i=0;i<200;i++){
 g.shadowRoot.querySelectorAll('tr').forEach(r=>{});
 g._getRenderedRows().forEach(r=>{const t=[...r.querySelectorAll('td')].map(c=>c.innerText.trim());if(t[0])seen.set(t[2],t)});
 const before=g.scrollTop;
 g.scrollTop+=300;
 await new Promise(r=>setTimeout(r,150));
 if(g.scrollTop===before)break;
}
const all=[...seen.values()];
return {total:all.length,lab:all.filter(t=>t[4].includes('Laboratory')).map(t=>t.join('|'))};
}

