input.function:
async () => {
const targets=['walter.brennan@laboratory.example','louisa.lindqvist@laboratory.example','marguerite.bennett@laboratory.example','eula.selvi@laboratory.example','jordan.novak@laboratory.example'];
const g=document.querySelector('vaadin-grid');
const sleep=ms=>new Promise(r=>setTimeout(r,ms));
const rowsInfo=()=>g._getRenderedRows().map(r=>{const t=[...r.children].map(td=>{const n=td.querySelector('slot').assignedNodes()[0];return n?n.textContent.trim():''});return {r,t}});
const log=[];
for(const em of targets){
 let found=null;
 const table=g.shadowRoot.querySelector('#table');
 for(let y=0;y<=7000&&!found;y+=200){table.scrollTop=y;await sleep(200);found=rowsInfo().find(x=>x.t[2]===em);}
 if(!found){log.push('notfound '+em);continue;}
 if(!found.t[3].startsWith('Closed')||!found.t[4].startsWith('Laboratory')){log.push('mismatch '+em);continue;}
 found.r.children[0].click();
 await sleep(800);
 const email=[...document.querySelectorAll('vaadin-email-field,vaadin-text-field')].map(f=>f.value);
 if(!email.includes(em)){log.push('formmismatch '+em+' '+email);continue;}
 const btn=[...document.querySelectorAll('vaadin-button')].find(b=>b.textContent.trim()==='Delete');
 btn.click();
 await sleep(1000);
 log.push('deleted '+em+' size '+g.size);
}
return log;
}

